-- Install only through protected-main applier with separate exact paid-state readback.
-- No ledger, wallet, cache, certificate, cron, data or GEN changes.
BEGIN;
SET LOCAL lock_timeout='1s';SET LOCAL statement_timeout='5s';SET LOCAL transaction_timeout='60s';
DO $cash_assert_presence_actual$BEGIN IF current_user<>'postgres'OR session_user<>'postgres'OR NULLIF(current_setting('request.jwt.claims',true),'')IS NOT NULL OR NULLIF(current_setting('request.jwt.claim.role',true),'')IS NOT NULL THEN RAISE EXCEPTION 'cash_assert_presence_postgres_required';END IF;IF md5(pg_get_functiondef('public.fn_assert_cash_commission_period(uuid,uuid,timestamptz,timestamptz)'::regprocedure))<>'0df1c3e9fe3e1a0e53a043baf57127d7'OR(SELECT to_jsonb(p)-'prosrc'FROM pg_proc p WHERE oid='public.fn_assert_cash_commission_period(uuid,uuid,timestamptz,timestamptz)'::regprocedure)IS DISTINCT FROM $actual_meta${"oid":"34785312","proacl":["postgres=X/postgres","service_role=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"13573","proname":"fn_assert_cash_commission_period","prorows":0,"pronargs":4,"proowner":"16384","proconfig":["search_path=public"],"proretset":false,"prosecdef":true,"prorettype":"2278","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["p_union_id","p_club_id","p_from","p_to"],"proargtypes":["2950","2950","1184","1184"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"s","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}$actual_meta$::jsonb THEN RAISE EXCEPTION 'cash_assert_presence_exact_actual_owner_changed';END IF;IF public.fn_platform_frozen()OR extract(minute FROM clock_timestamp()AT TIME ZONE 'UTC')>=50 OR extract(minute FROM clock_timestamp()AT TIME ZONE 'UTC')<3 THEN RAISE EXCEPTION 'cash_assert_presence_install_frozen_or_cutover';END IF;IF EXISTS(SELECT FROM supabase_migrations.schema_migrations WHERE version='20261030143333')THEN RAISE EXCEPTION 'cash_assert_presence_version_already_recorded';END IF;END$cash_assert_presence_actual$;
